/* The wildflower patch. GENERATED by build/build_flowers.py — edit this template, not js/effects/flowers.js. `data-static` switches the growing off, which is what draw.html does. Load userflowers.js first. */

(function () {
  'use strict';

  // How near the pointer a flower has to be to open, as a fraction of the patch.
  const BLOOM_RADIUS = 0.075;

  const MARKUP = `__MARKUP__`;

  const host = document.querySelector('.flowers');
  if (!host) return;
  host.innerHTML = MARKUP;

  const svg = host.querySelector('svg');
  // The artwork's own size would fix it on screen; the page's .flowers box decides instead.
  svg.removeAttribute('width');
  svg.removeAttribute('height');

  if (window.UserFlowers) window.UserFlowers.applyTo(svg);

  // Each centre as a fraction of the patch, measured once so the test below is arithmetic.
  function collect() {
    return Array.from(svg.querySelectorAll('.flower')).map((flower) => {
      const box = flower.querySelector('.head').getBBox();
      return {
        el: flower,
        fx: (box.x + box.width / 2) / 447,
        fy: (box.y + box.height / 2) / 114,
        open: false,
      };
    });
  }

  let spots = collect();

  if (host.hasAttribute('data-static')) return;

  let pointerX = -9999;
  let pointerY = -9999;
  let pending = false;

  document.addEventListener('mousemove', (e) => {
    pointerX = e.clientX;
    pointerY = e.clientY;
    schedule();
  });

  document.addEventListener('mouseleave', () => {
    pointerX = pointerY = -9999;
    schedule();
  });

  window.addEventListener('resize', schedule);
  document.addEventListener('beetalk', schedule);

  // At most one pass per frame however many events arrive.
  function schedule() {
    if (pending) return;
    pending = true;
    requestAnimationFrame(update);
  }

  function update() {
    pending = false;

    // The bee's bubble covers the patch and the pointer is not the bee's any more.
    if (document.documentElement.classList.contains('bee-talking')) {
      closeAll();
      return;
    }

    const rect = svg.getBoundingClientRect();
    if (!rect.width) return;

    const radius = rect.width * BLOOM_RADIUS;

    for (const spot of spots) {
      const dx = rect.left + spot.fx * rect.width - pointerX;
      const dy = rect.top + spot.fy * rect.height - pointerY;
      const open = Math.hypot(dx, dy) < radius;
      if (open !== spot.open) {
        spot.open = open;
        spot.el.classList.toggle('bloom', open);
      }
    }
  }

  function closeAll() {
    for (const spot of spots) {
      if (!spot.open) continue;
      spot.open = false;
      spot.el.classList.remove('bloom');
    }
  }
})();
